window.kbPageData["views/entry/k-8022240ccb40c678"] = {"key":"entry/k-8022240ccb40c678","state":{"route":"entry/k-8022240ccb40c678"},"node":{"id":"k-8022240ccb40c678","mode":"k","title":"条件命题的传递性","type":"原理与机制","domain":"形式逻辑","reading":"","intro":"","priority":100,"aliases":[],"qs":["江苏 2024 C类 行测#92"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"若甲成立必推出乙成立，乙成立又必推出丙成立，则甲成立必推出丙成立。串联时，前一命题的后件须与后一命题的前件一致。","review":{"definition":"若甲成立必推出乙成立，乙成立又必推出丙成立，则甲成立必推出丙成立。串联时，前一命题的后件须与后一命题的前件一致。","explanation":"第92题中，“只有乙参加，甲才参加”给出的方向是甲参加推出乙参加。接着由乙参加推出丙参加，再由丙参加推出丁不参加。因此甲参加时丁必不参加，C项所说的甲和丁同时参加不可能为真。","references":[],"evidence":"将（1）（2）（3）串联可得","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2024 C类 行测#92":{"paper":"江苏 2024 C类 行测","n":92,"mod":"判断推理","src":["3f1ec77ae8a18519b57e.pdf",19],"asrc":["02d6b49839583bdaf297.pdf",27],"card":"79fa5756e135d438d56147d7","links":[{"id":"k-8022240ccb40c678","role":"解题依据","why":"前一蕴含的后件与后一蕴含的前件一致时，可以跨过中间条件继续推导。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-8022240ccb40c678":[["江苏 2024 C类 行测#92"]]}};
